    """把最终组装类注入每个域模块的全局名 `DouyinAPI`。

    幂等：重复调用安全（后注入覆盖前值，值相同）。
    """
    if cls is None:
        raise ValueError("bind_all() requires the assembled DouyinAPI class, got None")
    for dom in DOMAIN_MODULES:
        try:
            mod = importlib.import_module(f"dy_apis.client_{dom}")
        except ImportError as err:
            raise ImportError(
                f"domain module 'dy_apis.client_{dom}' listed in DOMAIN_MODULES "
                "does not exist; keep DOMAIN_MODULES in sync with douyin_api.py"
            ) from err
        mod.DouyinAPI = cls

